
import { showGreeting } from "./greeting.js";
import { createCounter } from "./counter.js";

const nameInput = document.querySelector("#name-input");
const greetButton = document.querySelector("#greet-button");
const greetingResult = document.querySelector("#greeting-result");

const counterValue = document.querySelector("#counter-value");
const increaseButton = document.querySelector("#increase-button");
const decreaseButton = document.querySelector("#decrease-button");
const resetButton = document.querySelector("#reset-button");

const counter = createCounter();

greetButton.addEventListener("click", () => {
  const name = nameInput.value.trim();

  if (name) {
    greetingResult.textContent = showGreeting(name);
  } else {
    greetingResult.textContent = "Введіть своє ім'я!";
  }
});

increaseButton.addEventListener("click", () => {
  counterValue.textContent = counter.increase();
});

decreaseButton.addEventListener("click", () => {
  counterValue.textContent = counter.decrease();
});

resetButton.addEventListener("click", () => {
  counterValue.textContent = counter.reset();
});
